const player=document.querySelector('#player'),video=player.querySelector('video');
const labels={feed:'信息流',speech:'口播',ai:'AI创意短片',viral:'爆款视频'};
function play(item){document.querySelector('#video-title').textContent=item.title;document.querySelector('#video-category').textContent=[labels[item.group],item.category,item.account].filter(Boolean).join(' / ');document.querySelector('#play-error').hidden=true;document.querySelector('#direct-video').href=item.file;video.src=item.file;video.poster=item.poster;player.showModal();video.play().catch(()=>{});}
player.querySelector('.modal-close').onclick=()=>player.close();player.addEventListener('close',()=>{video.pause();video.removeAttribute('src');video.load();});video.onerror=()=>document.querySelector('#play-error').hidden=false;player.onclick=e=>{if(e.target===player)player.close();};
const duration=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
function card(item){const b=document.createElement('button');b.className='media-tile';b.setAttribute('aria-label',`播放 ${item.title}`);const thumb=document.createElement('span');thumb.className='thumbnail';const img=document.createElement('img');img.src=item.poster;img.alt='';img.loading='lazy';thumb.append(img);const mark=document.createElement('span');mark.className='play-mark';mark.textContent='▶';thumb.append(mark);const time=document.createElement('span');time.className='duration';time.textContent=duration(item.duration);thumb.append(time);b.append(thumb);const meta=document.createElement('span');meta.className='tile-meta';meta.textContent=item.category||labels[item.group];b.append(meta);const name=document.createElement('b');name.className='tile-title';name.textContent=item.title;b.append(name);if(item.account){const account=document.createElement('span');account.className='tile-account';account.textContent=item.account;b.append(account);}b.onclick=()=>play(item);return b;}
fetch('media/videos.json').then(r=>{if(!r.ok)throw Error('目录未加载');return r.json()}).then(items=>{document.querySelectorAll('[data-group]').forEach(g=>items.filter(i=>i.group===g.dataset.group).forEach(i=>g.append(card(i))));document.querySelector('#work-status').textContent=`共 ${items.length} 条视频作品`;}).catch(()=>{const status=document.querySelector('#work-status');status.className='load-error';status.textContent='作品加载失败，请刷新页面重试。';});
const jobs=[{period:'2024.03 — 2025.01',title:'IP编导 · 实习',description:'参与升学赛道内容策划、脚本撰写与素材整理，配合视频生产和内容复盘。',tags:['内容策划','脚本撰写','素材整理']},{period:'2025.03 — 2026.09',title:'IP编导',description:'独立操盘费老师教育思维账号，统筹升学就业内容规划，完成脚本创作及迭代打磨；搭建选题矩阵、案例库与用户问题库。',tags:['IP运营','选题规划','脚本迭代']}];
document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{const j=jobs[Number(b.dataset.job)];document.querySelector('#job-period').textContent=j.period;document.querySelector('#job-title').textContent=j.title;document.querySelector('#job-description').textContent=j.description;document.querySelector('#job-tags').replaceChildren(...j.tags.map(t=>{const s=document.createElement('span');s.textContent=t;return s;}));document.querySelectorAll('[data-job]').forEach(v=>{v.classList.toggle('selected',v===b);v.setAttribute('aria-pressed',String(v===b));});});
const links=[...document.querySelectorAll('.nav-links a')];const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -55%'});links.forEach(a=>io.observe(document.querySelector(a.hash)));
const lb=document.querySelector('#lightbox');document.querySelector('.zoomable').onclick=e=>{lb.querySelector('img').src=e.currentTarget.dataset.src;lb.showModal()};lb.querySelector('button').onclick=()=>lb.close();lb.onclick=e=>{if(e.target===lb)lb.close()};
